-- FundedFlow local journal: core schema (migration 0001)
--
-- Reference: docs/data-model.md
--
-- Conventions
--   * Every table is STRICT. Booleans are INTEGER 0/1 with a CHECK.
--   * IDs are TEXT, generated by the app (UUIDv7) so records are stable if
--     optional sync is ever added. Built-in seed rows use readable fixed IDs
--     such as 'builtin:instrument:ES'.
--   * Instants are UTC ISO-8601 TEXT with millisecond precision and a 'Z'
--     suffix (2026-10-19T14:30:05.123Z). Calendar days are 'YYYY-MM-DD'.
--   * Money is INTEGER micro-units of the account currency (1 USD = 1_000_000).
--     This is exact for fractional-cent tick values (M6E = $0.625/tick).
--   * Prices and quantities are canonical decimal TEXT ('4512.25', '2') and are
--     parsed with a decimal type in Rust. They are never stored as REAL.
--   * Original CSV rows (import_rows.raw_json) are immutable.
--
-- PRAGMA foreign_keys = ON must be set on every connection (SQLite default is OFF).

-- ---------------------------------------------------------------------------
-- App metadata and settings
-- ---------------------------------------------------------------------------

CREATE TABLE app_meta (
    key   TEXT PRIMARY KEY,
    value TEXT NOT NULL
) STRICT;
-- Expected keys: journal_id (written once at first run), created_at,
-- created_by_app_version.

CREATE TABLE settings (
    key        TEXT PRIMARY KEY,
    value_json TEXT NOT NULL CHECK (json_valid(value_json)),
    updated_at TEXT NOT NULL
) STRICT;

-- ---------------------------------------------------------------------------
-- Firms, programmes, accounts
-- ---------------------------------------------------------------------------

CREATE TABLE firms (
    id         TEXT PRIMARY KEY,
    name       TEXT NOT NULL CHECK (length(trim(name)) > 0),
    website    TEXT,
    notes_md   TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
) STRICT;
CREATE UNIQUE INDEX ux_firms_name ON firms (name COLLATE NOCASE) WHERE deleted_at IS NULL;

CREATE TABLE programmes (
    id             TEXT PRIMARY KEY,
    firm_id        TEXT NOT NULL REFERENCES firms (id) ON DELETE RESTRICT,
    name           TEXT NOT NULL CHECK (length(trim(name)) > 0),
    programme_type TEXT NOT NULL DEFAULT 'evaluation_to_funded'
        CHECK (programme_type IN ('evaluation_to_funded', 'instant_funding', 'other')),
    notes_md       TEXT,
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL,
    deleted_at     TEXT
) STRICT;
CREATE UNIQUE INDEX ux_programmes_firm_name
    ON programmes (firm_id, name COLLATE NOCASE) WHERE deleted_at IS NULL;

-- Accounts are hard-deleted (with everything that belongs to them); closing
-- or archiving an account is done with status = 'closed'.
CREATE TABLE accounts (
    id                      TEXT PRIMARY KEY,
    -- Optional prop firm. The app finds-or-creates the firm by name.
    firm_id                 TEXT REFERENCES firms (id) ON DELETE RESTRICT,
    programme_id            TEXT REFERENCES programmes (id) ON DELETE RESTRICT,
    -- An evaluation that passes usually becomes a new sim-funded account with
    -- a new number and balance. This links the funded account to its origin.
    parent_account_id       TEXT REFERENCES accounts (id) ON DELETE SET NULL,
    name                    TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 100),
    broker                  TEXT,            -- broker or platform, e.g. 'Tradovate', 'Rithmic'
    external_ref            TEXT,            -- account number shown in platform exports
    account_type            TEXT NOT NULL DEFAULT 'evaluation'
        CHECK (account_type IN ('evaluation', 'sim_funded', 'live_funded', 'personal', 'demo', 'other')),
    status                  TEXT NOT NULL DEFAULT 'active'
        CHECK (status IN ('active', 'paused', 'passed', 'failed', 'closed')),
    currency                TEXT NOT NULL DEFAULT 'USD' CHECK (currency GLOB '[A-Z][A-Z][A-Z]'),
    account_size_micros     INTEGER CHECK (account_size_micros IS NULL OR account_size_micros > 0),
    starting_balance_micros INTEGER NOT NULL CHECK (starting_balance_micros >= 0),
    timezone                TEXT NOT NULL,   -- IANA zone used for the trading-day reset
    trading_day_reset_time  TEXT NOT NULL DEFAULT '17:00'
        CHECK (trading_day_reset_time GLOB '[0-2][0-9]:[0-5][0-9]'),
    opened_on               TEXT CHECK (opened_on IS NULL OR opened_on GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
    notes_md                TEXT,
    created_at              TEXT NOT NULL,
    updated_at              TEXT NOT NULL,
    CHECK (parent_account_id IS NULL OR parent_account_id <> id)
) STRICT;
CREATE UNIQUE INDEX ux_accounts_broker_ref
    ON accounts (broker COLLATE NOCASE, external_ref)
    WHERE external_ref IS NOT NULL;
CREATE INDEX ix_accounts_firm ON accounts (firm_id);
CREATE INDEX ix_accounts_programme ON accounts (programme_id);

-- Status history; written by the app whenever accounts.status changes.
CREATE TABLE account_status_events (
    id           TEXT PRIMARY KEY,
    account_id   TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,
    status       TEXT NOT NULL
        CHECK (status IN ('active', 'paused', 'passed', 'failed', 'closed')),
    effective_at TEXT NOT NULL,
    note         TEXT,
    created_at   TEXT NOT NULL
) STRICT;
CREATE INDEX ix_status_events_account ON account_status_events (account_id, effective_at);

-- Non-trade balance movements. Payouts and resets change the balance the
-- drawdown rules see; evaluation/activation fees do not (affects_balance = 0)
-- but are kept for later account-ROI reporting.
CREATE TABLE account_ledger_entries (
    id              TEXT PRIMARY KEY,
    account_id      TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,
    kind            TEXT NOT NULL
        CHECK (kind IN ('balance_correction', 'payout', 'reset', 'evaluation_fee',
                        'activation_fee', 'reset_fee', 'other')),
    amount_micros   INTEGER NOT NULL,  -- signed effect; payouts are negative
    affects_balance INTEGER NOT NULL CHECK (affects_balance IN (0, 1)),
    effective_at    TEXT NOT NULL,
    trading_day     TEXT NOT NULL CHECK (trading_day GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
    note            TEXT,
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL,
    deleted_at      TEXT
) STRICT;
CREATE INDEX ix_ledger_account_day ON account_ledger_entries (account_id, trading_day);

-- ---------------------------------------------------------------------------
-- Versioned rulebooks
-- ---------------------------------------------------------------------------

CREATE TABLE rulebook_versions (
    id                TEXT PRIMARY KEY,
    account_id        TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,
    version_number    INTEGER NOT NULL CHECK (version_number >= 1),
    status            TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft', 'active', 'retired')),
    -- First trading day this version governs. A version applies until the
    -- next active version's effective_from.
    effective_from    TEXT NOT NULL CHECK (effective_from GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
    source            TEXT NOT NULL DEFAULT 'manual' CHECK (source IN ('manual', 'template', 'copied')),
    source_reference  TEXT,            -- e.g. firm help-centre URL and date read
    verified_at       TEXT,            -- when the user confirmed it matches the firm
    activated_at      TEXT,
    notes_md          TEXT,
    created_at        TEXT NOT NULL,
    updated_at        TEXT NOT NULL,
    deleted_at        TEXT,
    UNIQUE (account_id, version_number),
    CHECK ((status = 'draft') = (activated_at IS NULL))
) STRICT;
CREATE UNIQUE INDEX ux_rulebook_active_effective
    ON rulebook_versions (account_id, effective_from)
    WHERE status = 'active' AND deleted_at IS NULL;

-- Active and retired versions are frozen. The only permitted change is the
-- active -> retired transition (plus updated_at). Edits require a new version.
CREATE TRIGGER trg_rulebook_versions_frozen
BEFORE UPDATE ON rulebook_versions
WHEN OLD.status <> 'draft'
 AND NOT (OLD.status = 'active' AND NEW.status = 'retired'
          AND NEW.account_id IS OLD.account_id
          AND NEW.version_number IS OLD.version_number
          AND NEW.effective_from IS OLD.effective_from
          AND NEW.source IS OLD.source
          AND NEW.source_reference IS OLD.source_reference
          AND NEW.verified_at IS OLD.verified_at
          AND NEW.activated_at IS OLD.activated_at
          AND NEW.notes_md IS OLD.notes_md
          AND NEW.deleted_at IS OLD.deleted_at)
BEGIN
    SELECT RAISE(ABORT, 'rulebook version is frozen; create a new version');
END;

CREATE TABLE rules (
    id                  TEXT PRIMARY KEY,
    rulebook_version_id TEXT NOT NULL REFERENCES rulebook_versions (id) ON DELETE CASCADE,
    rule_type           TEXT NOT NULL CHECK (rule_type IN (
        'profit_target',       -- {"amount_micros"}
        'daily_loss_limit',    -- {"amount_micros","basis":"realized"|"realized_and_unrealized"}
        'max_drawdown',        -- {"mode":"static"|"eod_trailing"|"intraday_trailing",
                               --  "amount_micros","includes_unrealized",
                               --  "lock":{"trigger_balance_micros","locked_floor_micros"}|null}
        'min_trading_days',    -- {"days","min_day_profit_micros"|null}
        'consistency',         -- {"max_best_day_share_bps"}  (e.g. 3000 = 30%)
        'max_position_size',   -- {"max_contracts","symbol_root"|null}
        'max_trades_per_day',  -- {"count"}  (personal process limit)
        'manual_check'         -- {"description"}  news, hours, copy-trading bans...
    )),
    origin              TEXT NOT NULL DEFAULT 'firm' CHECK (origin IN ('firm', 'personal')),
    -- 'manual_confirmation' rules are never silently treated as compliant.
    evaluation          TEXT NOT NULL DEFAULT 'calculated'
        CHECK (evaluation IN ('calculated', 'manual_confirmation')),
    -- 'unknown' means the firm's value has not been confirmed; risk status
    -- must be 'needs_setup'/'unknown' rather than 'safe'.
    value_state         TEXT NOT NULL DEFAULT 'known' CHECK (value_state IN ('known', 'unknown')),
    params_json         TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(params_json)),
    label               TEXT,
    sort_order          INTEGER NOT NULL DEFAULT 0,
    created_at          TEXT NOT NULL,
    updated_at          TEXT NOT NULL,
    CHECK (rule_type <> 'manual_check' OR evaluation = 'manual_confirmation')
) STRICT;
CREATE UNIQUE INDEX ux_rules_one_per_type
    ON rules (rulebook_version_id, rule_type, origin)
    WHERE rule_type NOT IN ('manual_check', 'max_position_size');
CREATE INDEX ix_rules_version ON rules (rulebook_version_id);

CREATE TRIGGER trg_rules_frozen_insert
BEFORE INSERT ON rules
WHEN (SELECT status FROM rulebook_versions WHERE id = NEW.rulebook_version_id) <> 'draft'
BEGIN
    SELECT RAISE(ABORT, 'rules of an activated rulebook version cannot change');
END;

CREATE TRIGGER trg_rules_frozen_update
BEFORE UPDATE ON rules
WHEN (SELECT status FROM rulebook_versions WHERE id = OLD.rulebook_version_id) <> 'draft'
BEGIN
    SELECT RAISE(ABORT, 'rules of an activated rulebook version cannot change');
END;

-- Deleting a whole account cascades through rulebook_versions; that path is
-- allowed because the parent version row is being deleted in the same statement.
CREATE TRIGGER trg_rules_frozen_delete
BEFORE DELETE ON rules
WHEN (SELECT status FROM rulebook_versions WHERE id = OLD.rulebook_version_id) <> 'draft'
BEGIN
    SELECT RAISE(ABORT, 'rules of an activated rulebook version cannot change');
END;

-- ---------------------------------------------------------------------------
-- Instruments
-- ---------------------------------------------------------------------------

CREATE TABLE instruments (
    id           TEXT PRIMARY KEY,
    symbol_root  TEXT NOT NULL,          -- 'MNQ' (contract month stripped)
    display_name TEXT,
    asset_class  TEXT NOT NULL CHECK (asset_class IN ('future', 'forex', 'cfd', 'equity', 'crypto', 'other')),
    exchange     TEXT,
    currency     TEXT NOT NULL DEFAULT 'USD' CHECK (currency GLOB '[A-Z][A-Z][A-Z]'),
    point_value  TEXT NOT NULL,          -- currency per 1.0 price move per contract
    tick_size    TEXT,
    is_built_in  INTEGER NOT NULL DEFAULT 0 CHECK (is_built_in IN (0, 1)),
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL,
    deleted_at   TEXT
) STRICT;
CREATE UNIQUE INDEX ux_instruments_root ON instruments (symbol_root) WHERE deleted_at IS NULL;

-- ---------------------------------------------------------------------------
-- Attachments (files live in <app data>/attachments/<storage_key>)
-- ---------------------------------------------------------------------------

CREATE TABLE attachments (
    id            TEXT PRIMARY KEY,
    kind          TEXT NOT NULL CHECK (kind IN ('screenshot', 'import_source', 'other')),
    storage_key   TEXT NOT NULL UNIQUE,   -- relative, opaque; never an absolute path
    original_name TEXT,
    mime_type     TEXT NOT NULL,
    byte_size     INTEGER NOT NULL CHECK (byte_size >= 0),
    sha256        TEXT NOT NULL CHECK (length(sha256) = 64),
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL,
    deleted_at    TEXT,
    CHECK (substr(storage_key, 1, 1) NOT IN ('/', '\') AND storage_key NOT GLOB '[A-Za-z]:*'
           AND instr(storage_key, '..') = 0)
) STRICT;
CREATE INDEX ix_attachments_sha ON attachments (sha256);

-- ---------------------------------------------------------------------------
-- CSV import
-- ---------------------------------------------------------------------------

CREATE TABLE csv_mapping_profiles (
    id              TEXT PRIMARY KEY,
    name            TEXT NOT NULL,
    platform        TEXT,
    column_map_json TEXT NOT NULL CHECK (json_valid(column_map_json)),
    options_json    TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(options_json)),
    is_built_in     INTEGER NOT NULL DEFAULT 0 CHECK (is_built_in IN (0, 1)),
    created_at      TEXT NOT NULL,
    updated_at      TEXT NOT NULL,
    deleted_at      TEXT
) STRICT;

-- One row per import attempt. A 'committed' batch was written in a single
-- transaction; a 'failed' batch records an attempt that wrote no trades.
CREATE TABLE import_batches (
    id                    TEXT PRIMARY KEY,
    account_id            TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,
    source_attachment_id  TEXT REFERENCES attachments (id) ON DELETE SET NULL,
    file_name             TEXT NOT NULL,
    file_sha256           TEXT NOT NULL CHECK (length(file_sha256) = 64),
    file_size             INTEGER NOT NULL CHECK (file_size >= 0),
    mapping_profile_id    TEXT REFERENCES csv_mapping_profiles (id) ON DELETE SET NULL,
    -- Exact mapping/options/headers used, so history stays explainable.
    mapping_snapshot_json TEXT NOT NULL CHECK (json_valid(mapping_snapshot_json)),
    source_timezone       TEXT NOT NULL,  -- zone of naive timestamps in the file
    status                TEXT NOT NULL CHECK (status IN ('committed', 'failed')),
    row_count             INTEGER NOT NULL DEFAULT 0 CHECK (row_count >= 0),
    imported_count        INTEGER NOT NULL DEFAULT 0 CHECK (imported_count >= 0),
    -- skipped = duplicates + blank rows; duplicates are also counted separately.
    skipped_count         INTEGER NOT NULL DEFAULT 0 CHECK (skipped_count >= 0),
    duplicate_count       INTEGER NOT NULL DEFAULT 0 CHECK (duplicate_count >= 0),
    failed_count          INTEGER NOT NULL DEFAULT 0 CHECK (failed_count >= 0),
    error_summary         TEXT,
    created_at            TEXT NOT NULL,
    completed_at          TEXT NOT NULL,
    CHECK (duplicate_count <= skipped_count),
    CHECK (status <> 'committed' OR row_count = imported_count + skipped_count + failed_count),
    CHECK (status <> 'failed' OR (imported_count = 0 AND error_summary IS NOT NULL))
) STRICT;
CREATE INDEX ix_import_batches_account ON import_batches (account_id, created_at);
CREATE INDEX ix_import_batches_sha ON import_batches (account_id, file_sha256);

CREATE TABLE import_rows (
    id                    TEXT PRIMARY KEY,
    batch_id              TEXT NOT NULL REFERENCES import_batches (id) ON DELETE CASCADE,
    row_number            INTEGER NOT NULL CHECK (row_number >= 1),  -- 1 = first data row
    line_number           INTEGER NOT NULL CHECK (line_number >= 1), -- line in the file
    raw_json              TEXT NOT NULL CHECK (json_valid(raw_json)), -- original cells, immutable
    status                TEXT NOT NULL CHECK (status IN ('imported', 'duplicate', 'skipped', 'invalid')),
    issues_json           TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(issues_json)),
    duplicate_of_trade_id TEXT REFERENCES trades (id) ON DELETE SET NULL,
    UNIQUE (batch_id, row_number)
) STRICT;
CREATE INDEX ix_import_rows_status ON import_rows (batch_id, status);
CREATE INDEX ix_import_rows_duplicate_of ON import_rows (duplicate_of_trade_id);

CREATE TRIGGER trg_import_rows_raw_immutable
BEFORE UPDATE OF raw_json, batch_id, row_number, line_number ON import_rows
BEGIN
    SELECT RAISE(ABORT, 'original import rows are immutable');
END;

-- ---------------------------------------------------------------------------
-- Trades (one row per round trip; manual or imported)
-- ---------------------------------------------------------------------------

-- Trades are soft-deleted (deleted_at) so that an imported trade the user
-- deleted keeps its dedup_key and is not resurrected by re-importing the file.
CREATE TABLE trades (
    id                  TEXT PRIMARY KEY,
    account_id          TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,
    source              TEXT NOT NULL CHECK (source IN ('manual', 'csv_import')),
    import_batch_id     TEXT REFERENCES import_batches (id) ON DELETE CASCADE,
    import_row_id       TEXT REFERENCES import_rows (id) ON DELETE CASCADE,
    -- Idempotency key for imported trades, unique per account
    -- (see docs/data-model.md#duplicate-detection). NULL for manual trades.
    dedup_key           TEXT,
    broker_trade_id     TEXT,
    symbol              TEXT NOT NULL CHECK (length(trim(symbol)) BETWEEN 1 AND 32),
    instrument_id       TEXT REFERENCES instruments (id) ON DELETE SET NULL,
    side                TEXT NOT NULL CHECK (side IN ('long', 'short')),
    quantity            TEXT NOT NULL,
    entry_at            TEXT NOT NULL CHECK (entry_at GLOB
        '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]T[0-2][0-9]:[0-5][0-9]:[0-6][0-9].[0-9][0-9][0-9]Z'),
    entry_price         TEXT NOT NULL,
    exit_at             TEXT CHECK (exit_at IS NULL OR exit_at GLOB
        '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]T[0-2][0-9]:[0-5][0-9]:[0-6][0-9].[0-9][0-9][0-9]Z'),
    exit_price          TEXT,
    fees_micros         INTEGER NOT NULL DEFAULT 0 CHECK (fees_micros >= 0),  -- all costs, positive
    -- Trading day the trade counts toward: the exit (or, while open, the
    -- entry) in the account's timezone and reset time. Recomputed when those change.
    trading_day         TEXT NOT NULL CHECK (trading_day GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
    -- P&L reported by the source (CSV column or manual entry), before fees.
    reported_pnl_micros INTEGER,
    -- Realized P&L in the account currency; see pnl_status for its origin.
    gross_pnl_micros    INTEGER,
    net_pnl_micros      INTEGER,
    pnl_status          TEXT NOT NULL CHECK (pnl_status IN
        ('calculated', 'reported', 'open', 'missing_instrument', 'currency_mismatch')),
    notes_md            TEXT,
    created_at          TEXT NOT NULL,
    updated_at          TEXT NOT NULL,
    deleted_at          TEXT,
    UNIQUE (account_id, dedup_key),
    CHECK ((source = 'csv_import') = (import_batch_id IS NOT NULL)),
    CHECK ((source = 'csv_import') = (dedup_key IS NOT NULL)),
    CHECK (import_row_id IS NULL OR import_batch_id IS NOT NULL),
    CHECK (quantity GLOB '[0-9]*' AND quantity NOT GLOB '*[^0-9.]*'
           AND quantity NOT GLOB '*.*.*' AND CAST(quantity AS REAL) > 0),
    CHECK ((entry_price GLOB '[0-9]*' OR entry_price GLOB '-[0-9]*')
           AND substr(entry_price, 2) NOT GLOB '*[^0-9.]*' AND entry_price NOT GLOB '*.*.*'),
    CHECK (exit_price IS NULL OR ((exit_price GLOB '[0-9]*' OR exit_price GLOB '-[0-9]*')
           AND substr(exit_price, 2) NOT GLOB '*[^0-9.]*' AND exit_price NOT GLOB '*.*.*')),
    CHECK ((exit_at IS NULL) = (exit_price IS NULL)),
    CHECK (exit_at IS NULL OR exit_at >= entry_at),
    CHECK ((pnl_status = 'open') = (exit_at IS NULL)),
    CHECK ((gross_pnl_micros IS NULL) = (net_pnl_micros IS NULL)),
    CHECK ((gross_pnl_micros IS NOT NULL) = (pnl_status IN ('calculated', 'reported'))),
    CHECK (net_pnl_micros IS NULL OR net_pnl_micros = gross_pnl_micros - fees_micros),
    CHECK (pnl_status <> 'reported' OR gross_pnl_micros = reported_pnl_micros)
) STRICT;
CREATE INDEX ix_trades_account_entry ON trades (account_id, entry_at);
CREATE INDEX ix_trades_account_day ON trades (account_id, trading_day);
CREATE INDEX ix_trades_batch ON trades (import_batch_id);
CREATE INDEX ix_trades_row ON trades (import_row_id);
CREATE INDEX ix_trades_instrument ON trades (instrument_id);

-- A trade never moves to another account, and its import provenance is fixed.
CREATE TRIGGER trg_trades_provenance_immutable
BEFORE UPDATE OF id, account_id, source, import_batch_id, import_row_id, dedup_key, created_at
ON trades
BEGIN
    SELECT RAISE(ABORT, 'trade account and import provenance are immutable');
END;

-- ---------------------------------------------------------------------------
-- Playbooks, checklists, tags
-- ---------------------------------------------------------------------------

CREATE TABLE strategies (
    id             TEXT PRIMARY KEY,
    name           TEXT NOT NULL CHECK (length(trim(name)) > 0),
    description_md TEXT,
    color          TEXT,
    is_archived    INTEGER NOT NULL DEFAULT 0 CHECK (is_archived IN (0, 1)),
    created_at     TEXT NOT NULL,
    updated_at     TEXT NOT NULL,
    deleted_at     TEXT
) STRICT;
CREATE UNIQUE INDEX ux_strategies_name ON strategies (name COLLATE NOCASE) WHERE deleted_at IS NULL;

-- scope 'trade': a strategy's entry/management checklist, reviewed per trade.
-- scope 'daily': personal process rules reviewed in the journal.
CREATE TABLE checklists (
    id          TEXT PRIMARY KEY,
    name        TEXT NOT NULL,
    scope       TEXT NOT NULL CHECK (scope IN ('trade', 'daily')),
    strategy_id TEXT REFERENCES strategies (id) ON DELETE CASCADE,
    is_archived INTEGER NOT NULL DEFAULT 0 CHECK (is_archived IN (0, 1)),
    created_at  TEXT NOT NULL,
    updated_at  TEXT NOT NULL,
    deleted_at  TEXT,
    CHECK (scope = 'trade' OR strategy_id IS NULL)
) STRICT;

CREATE TABLE checklist_items (
    id           TEXT PRIMARY KEY,
    checklist_id TEXT NOT NULL REFERENCES checklists (id) ON DELETE CASCADE,
    label        TEXT NOT NULL CHECK (length(trim(label)) > 0),
    sort_order   INTEGER NOT NULL DEFAULT 0,
    is_archived  INTEGER NOT NULL DEFAULT 0 CHECK (is_archived IN (0, 1)),
    created_at   TEXT NOT NULL,
    updated_at   TEXT NOT NULL,
    deleted_at   TEXT
) STRICT;
CREATE INDEX ix_checklist_items_checklist ON checklist_items (checklist_id, sort_order);

CREATE TABLE tags (
    id         TEXT PRIMARY KEY,
    name       TEXT NOT NULL CHECK (length(trim(name)) BETWEEN 1 AND 40),
    kind       TEXT NOT NULL DEFAULT 'general' CHECK (kind IN ('setup', 'mistake', 'emotion', 'general')),
    color      TEXT,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    deleted_at TEXT
) STRICT;
CREATE UNIQUE INDEX ux_tags_kind_name ON tags (kind, name COLLATE NOCASE) WHERE deleted_at IS NULL;

-- ---------------------------------------------------------------------------
-- Journal: trade reviews and journal entries
-- ---------------------------------------------------------------------------

-- Structured per-trade review (strategy, plan, rating). At most one per trade.
CREATE TABLE trade_reviews (
    id                    TEXT PRIMARY KEY,
    trade_id              TEXT NOT NULL REFERENCES trades (id) ON DELETE CASCADE,
    strategy_id           TEXT REFERENCES strategies (id) ON DELETE SET NULL,
    planned_entry_price   TEXT,
    planned_stop_price    TEXT,
    planned_target_price  TEXT,
    planned_risk_micros   INTEGER CHECK (planned_risk_micros IS NULL OR planned_risk_micros > 0),  -- 1R
    -- Optional manual excursions; FundedFlow has no price feed in v1.
    mae_micros            INTEGER,
    mfe_micros            INTEGER,
    execution_rating      INTEGER CHECK (execution_rating IS NULL OR execution_rating BETWEEN 1 AND 5),
    followed_plan         INTEGER CHECK (followed_plan IS NULL OR followed_plan IN (0, 1)),
    thesis_md             TEXT,
    reflection_md         TEXT,
    reviewed_at           TEXT,
    created_at            TEXT NOT NULL,
    updated_at            TEXT NOT NULL,
    deleted_at            TEXT
) STRICT;
CREATE UNIQUE INDEX ux_trade_reviews_trade ON trade_reviews (trade_id) WHERE deleted_at IS NULL;
CREATE INDEX ix_trade_reviews_strategy ON trade_reviews (strategy_id);

-- Free-form journal entry for an account, optionally about one trade of that
-- account. Hard-deleted; deleting the account deletes its entries, deleting
-- the trade only clears trade_id.
CREATE TABLE journal_entries (
    id         TEXT PRIMARY KEY,
    account_id TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,
    trade_id   TEXT REFERENCES trades (id) ON DELETE SET NULL,
    entry_at   TEXT NOT NULL CHECK (entry_at GLOB
        '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]T[0-2][0-9]:[0-5][0-9]:[0-6][0-9].[0-9][0-9][0-9]Z'),
    title      TEXT NOT NULL CHECK (length(trim(title)) BETWEEN 1 AND 200),
    body_md    TEXT NOT NULL DEFAULT '',
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
) STRICT;
CREATE INDEX ix_journal_account_entry ON journal_entries (account_id, entry_at);
CREATE INDEX ix_journal_trade ON journal_entries (trade_id);

CREATE TRIGGER trg_journal_trade_same_account_insert
BEFORE INSERT ON journal_entries
WHEN NEW.trade_id IS NOT NULL
 AND (SELECT account_id FROM trades WHERE id = NEW.trade_id) IS NOT NEW.account_id
BEGIN
    SELECT RAISE(ABORT, 'journal entry trade must belong to the same account');
END;

CREATE TRIGGER trg_journal_trade_same_account_update
BEFORE UPDATE OF trade_id, account_id ON journal_entries
WHEN NEW.trade_id IS NOT NULL
 AND (SELECT account_id FROM trades WHERE id = NEW.trade_id) IS NOT NEW.account_id
BEGIN
    SELECT RAISE(ABORT, 'journal entry trade must belong to the same account');
END;

CREATE TABLE checklist_results (
    id                  TEXT PRIMARY KEY,
    checklist_item_id   TEXT NOT NULL REFERENCES checklist_items (id) ON DELETE RESTRICT,
    item_label_snapshot TEXT NOT NULL,  -- label as it read when reviewed
    trade_review_id     TEXT REFERENCES trade_reviews (id) ON DELETE CASCADE,
    journal_entry_id    TEXT REFERENCES journal_entries (id) ON DELETE CASCADE,
    result              TEXT NOT NULL CHECK (result IN ('followed', 'missed', 'not_applicable')),
    note                TEXT,
    created_at          TEXT NOT NULL,
    updated_at          TEXT NOT NULL,
    deleted_at          TEXT,
    CHECK ((trade_review_id IS NULL) <> (journal_entry_id IS NULL))
) STRICT;
CREATE UNIQUE INDEX ux_checklist_results_review
    ON checklist_results (trade_review_id, checklist_item_id)
    WHERE trade_review_id IS NOT NULL AND deleted_at IS NULL;
CREATE UNIQUE INDEX ux_checklist_results_journal
    ON checklist_results (journal_entry_id, checklist_item_id)
    WHERE journal_entry_id IS NOT NULL AND deleted_at IS NULL;

CREATE TABLE trade_review_tags (
    trade_review_id TEXT NOT NULL REFERENCES trade_reviews (id) ON DELETE CASCADE,
    tag_id          TEXT NOT NULL REFERENCES tags (id) ON DELETE CASCADE,
    created_at      TEXT NOT NULL,
    PRIMARY KEY (trade_review_id, tag_id)
) STRICT, WITHOUT ROWID;
CREATE INDEX ix_trade_review_tags_tag ON trade_review_tags (tag_id);

CREATE TABLE journal_entry_tags (
    journal_entry_id TEXT NOT NULL REFERENCES journal_entries (id) ON DELETE CASCADE,
    tag_id           TEXT NOT NULL REFERENCES tags (id) ON DELETE CASCADE,
    created_at       TEXT NOT NULL,
    PRIMARY KEY (journal_entry_id, tag_id)
) STRICT, WITHOUT ROWID;
CREATE INDEX ix_journal_entry_tags_tag ON journal_entry_tags (tag_id);

CREATE TABLE attachment_links (
    id               TEXT PRIMARY KEY,
    attachment_id    TEXT NOT NULL REFERENCES attachments (id) ON DELETE CASCADE,
    trade_review_id  TEXT REFERENCES trade_reviews (id) ON DELETE CASCADE,
    journal_entry_id TEXT REFERENCES journal_entries (id) ON DELETE CASCADE,
    caption          TEXT,
    sort_order       INTEGER NOT NULL DEFAULT 0,
    created_at       TEXT NOT NULL,
    updated_at       TEXT NOT NULL,
    deleted_at       TEXT,
    CHECK ((trade_review_id IS NULL) <> (journal_entry_id IS NULL))
) STRICT;
CREATE INDEX ix_attachment_links_review ON attachment_links (trade_review_id);
CREATE INDEX ix_attachment_links_journal ON attachment_links (journal_entry_id);

-- ---------------------------------------------------------------------------
-- Risk calculation results (derived, rebuildable, but kept for traceability)
-- ---------------------------------------------------------------------------

CREATE TABLE account_snapshots (
    id                          TEXT PRIMARY KEY,
    account_id                  TEXT NOT NULL REFERENCES accounts (id) ON DELETE CASCADE,
    rulebook_version_id         TEXT REFERENCES rulebook_versions (id) ON DELETE CASCADE,
    trading_day                 TEXT NOT NULL CHECK (trading_day GLOB '[0-9][0-9][0-9][0-9]-[0-1][0-9]-[0-3][0-9]'),
    -- 1 = closing figures for the day; these rows form the end-of-day
    -- high-water-mark history used by eod_trailing drawdown.
    is_end_of_day               INTEGER NOT NULL CHECK (is_end_of_day IN (0, 1)),
    -- Data freshness: the newest trade/ledger entry included.
    data_as_of                  TEXT,
    data_source                 TEXT NOT NULL CHECK (data_source IN ('csv_import', 'manual', 'mixed', 'none')),
    calculated_at               TEXT NOT NULL,
    engine_version              TEXT NOT NULL,
    inputs_hash                 TEXT NOT NULL,
    fees_included               INTEGER NOT NULL DEFAULT 1 CHECK (fees_included IN (0, 1)),
    unrealized_included         INTEGER NOT NULL DEFAULT 0 CHECK (unrealized_included IN (0, 1)),
    balance_micros              INTEGER NOT NULL,
    realized_day_pnl_micros     INTEGER NOT NULL,
    unrealized_pnl_micros       INTEGER,
    daily_loss_limit_micros     INTEGER,
    daily_loss_remaining_micros INTEGER,
    drawdown_mode               TEXT CHECK (drawdown_mode IS NULL OR drawdown_mode IN ('static', 'eod_trailing', 'intraday_trailing')),
    high_water_mark_micros      INTEGER,
    drawdown_floor_micros       INTEGER,
    drawdown_headroom_micros    INTEGER,
    drawdown_locked             INTEGER NOT NULL DEFAULT 0 CHECK (drawdown_locked IN (0, 1)),
    profit_target_micros        INTEGER,
    trading_days_completed      INTEGER NOT NULL DEFAULT 0,
    trading_days_required       INTEGER,
    status                      TEXT NOT NULL CHECK (status IN ('safe', 'caution', 'stop', 'unknown', 'needs_setup')),
    status_reasons_json         TEXT NOT NULL DEFAULT '[]' CHECK (json_valid(status_reasons_json)),
    -- Inputs, formula steps, rule IDs and contributing trade IDs.
    explanation_json            TEXT NOT NULL CHECK (json_valid(explanation_json))
) STRICT;
CREATE INDEX ix_snapshots_account_day ON account_snapshots (account_id, trading_day, calculated_at);
CREATE UNIQUE INDEX ux_snapshots_eod
    ON account_snapshots (account_id, trading_day, engine_version, inputs_hash) WHERE is_end_of_day = 1;

-- ---------------------------------------------------------------------------
-- Audit trail and (disabled) sync outbox
-- ---------------------------------------------------------------------------

CREATE TABLE audit_events (
    id           TEXT PRIMARY KEY,
    occurred_at  TEXT NOT NULL,
    actor        TEXT NOT NULL DEFAULT 'user' CHECK (actor IN ('user', 'system')),
    action       TEXT NOT NULL,    -- e.g. 'import.committed', 'rulebook.activated'
    entity_type  TEXT NOT NULL,
    entity_id    TEXT,
    account_id   TEXT,             -- no FK: audit history outlives deleted accounts
    summary      TEXT NOT NULL,
    details_json TEXT NOT NULL DEFAULT '{}' CHECK (json_valid(details_json))
) STRICT;
CREATE INDEX ix_audit_entity ON audit_events (entity_type, entity_id);
CREATE INDEX ix_audit_occurred ON audit_events (occurred_at);

CREATE TRIGGER trg_audit_append_only_update
BEFORE UPDATE ON audit_events
BEGIN
    SELECT RAISE(ABORT, 'audit events are append-only');
END;
-- DELETE is intentionally allowed: "permanently delete my journal" must work.

-- Reserved for optional future sync. Nothing writes to this table in v1.
CREATE TABLE sync_outbox (
    id          INTEGER PRIMARY KEY,
    entity_type TEXT NOT NULL,
    entity_id   TEXT NOT NULL,
    operation   TEXT NOT NULL CHECK (operation IN ('upsert', 'delete')),
    changed_at  TEXT NOT NULL,
    sent_at     TEXT
) STRICT;
